        if era == 'canal':
            if level >= 2:
                score += 35.0
            elif turn >= 8:
                score -= 60.0

    elif atype == 'develop':
        inds = action.get('industries', [])
        if era == 'canal':
            if turn <= 5:
                score += 65.0
                if 'goods' in inds:
                    score += 15.0
                if 'cotton' in inds or 'brewery' in inds:
                    score += 10.0
            elif turn <= 7:
                score += 40.0
            else:
                score -= 60.0
        else: # rail
            score += 25.0 if turn <= 14 else -80.0

    elif atype == 'loan':
        if note.get('loan_warn', False) or (era == 'canal' and turn >= 9) or (era == 'rail' and turn >= 18):
            score -= 250.0
        elif money >= 18:
            score -= 100.0
        elif money <= 7:
            score += 90.0 if ((era == 'canal' and turn <= 6) or (era == 'rail' and turn <= 15)) else 40.0
        elif money <= 13:
            score += 45.0
        else:
            score -= 20.0
        if income_space < 10:
            score -= 80.0

    elif atype == 'scout':
        score -= 60.0

    elif atype == 'pass':
        score -= 1000.0

    # Budget check:
    rem_money = money - cost
    if rem_money < 2 and income_space <= 10 and turn > 1 and atype not in ('sell', 'loan'):
        score -= 15.0

    return score

