            if iron_cubes < 14:
                score += 35.0  # auto-sells to market immediately
            score += 75.0 + tile_vp * 5.0 + tile_inc * 4.0
            if era == "canal" and level >= 2:
                score += 40.0

        elif ind in ("cotton", "goods", "pottery"):
            if unlinked:
                if is_late_era:
                    score -= 120.0
                elif turn <= 2:
                    score += 35.0
                else:
                    score += 25.0
            else:
                if level >= 2:
                    score += 110.0 + tile_vp * 6.0 + tile_inc * 3.0
                elif ind == "goods":
                    score += 40.0 + tile_vp * 4.0
                elif ind == "pottery":
                    score += 105.0 + tile_vp * 6.0 + tile_inc * 3.0
                else:
                    score += 80.0 + tile_vp * 5.0 + tile_inc * 3.0

        if era == "canal":
            if level >= 2 and ind not in ("coal", "iron", "brewery"):
                score += 40.0
            elif is_late_era:
                score -= 70.0

    elif atype == "develop":
        inds = action.get("industries", [])
        if era == "canal":
            if turn <= 5:
                score += 90.0
                if "goods" in inds:
                    score += 20.0
                if "cotton" in inds:
                    score += 10.0
                if "brewery" in inds:
                    score += 12.0
            elif turn <= 7:
                score += 45.0
            else:
                score -= 60.0
        else:
            score += 25.0 if turn <= 14 else -80.0

    elif atype == "loan":
        if note.get("loan_warn", False) or is_very_late_era:
            score -= 250.0
        elif money >= 18:
            score -= 100.0
        elif money <= 7:
            if (era == "canal" and turn <= 6) or (era == "rail" and (turn <= 6 or turn <= 16)):
                score += 95.0
            else:
                score += 40.0
        elif money <= 13:
            score += 45.0
        else:
            score -= 20.0

        if income_space < 10:
            score -= 100.0

    elif atype == "scout":
        score -= 60.0

    elif atype == "pass":
        score -= 1000.0

    rem_money = money - cost
    if rem_money < 2 and income_space <= 10 and turn > 1 and atype not in ("sell", "loan"):
        score -= 15.0

    return score


def play_one_step() -> Tuple[bool, Dict[str, Any]]:
    status = http_get("/status")
    if not status.get("ok"):
        print(f"Status error: {status.get('error')}", file=sys.stderr)
        return False, status

    state = status.get("state", {})
    if state.get("game_over"):
        print("Game is already over!")
        return True, status

    legal = http_get("/legal")
    if not legal.get("ok"):
        print(f"Legal error: {legal.get('error')}", file=sys.stderr)
        return False, legal

    actions = legal.get("actions", [])
    if not actions:
        print("No legal actions available!")
        return True, status

    notes = parse_action_notes(legal.get("formatted", ""))
    summary = status.get("board_summary", {})

    scored: List[Tuple[float, Dict[str, Any]]] = []
    for a in actions:
        s = score_action(a, state, summary, notes)
        scored.append((s, a))

    scored.sort(key=lambda x: x[0], reverse=True)
    best_score, best_action = scored[0]
    aid = best_action["action_id"]

    print(f"\n--- SELECTING ACTION ---")
    print(f"State: Era={state.get('era')} | Turn={state.get('turn')} | ActionsLeft={state.get('actions_left')} | Cash=£{state.get('money')} | Inc={summary.get('income_pounds')} | VP={state.get('your_vp')} vs Automa={state.get('automa_vp')}")
    print(f"Chosen: [{aid:2d}] {best_action.get('description')} (Heuristic Score: {best_score:.1f})")
    if len(scored) > 1:
        s2, a2 = scored[1]
        print(f"Runner-up: [{a2['action_id']:2d}] {a2.get('description')} (Score: {s2:.1f})")

    result = http_post("/play", {"action_id": aid})
    if not result.get("ok"):
        print(f"Play ERROR: {result.get('error')}", file=sys.stderr)
        return False, result

    print(f">>> EXECUTED STEP #{result.get('executed_step')}: [{result.get('executed_action_id')}] {result.get('executed_description')}")

    game_over = result.get("game_over", False)
    return game_over, result


def main() -> int:
    parser = argparse.ArgumentParser(description="Brass Birmingham Autonomous Controller")
    parser.add_argument("--step", type=int, default=0, help="Play N steps (0 for run to completion)")
    args = parser.parse_args()

    steps_played = 0
    start_time = time.time()

    while True:
        status = http_get("/status")
        if status.get("state", {}).get("game_over"):
            print("\n=======================================================")
            print("MATCH COMPLETE!")
            preview = status.get("harbor_score_preview", {})
            print(f"Final Score: You {preview.get('your_vp')} VP vs Automa {preview.get('automa_vp')} VP (Margin: +{preview.get('vp_margin')} VP)")
            print(f"Won: {preview.get('won')}")
            print(f"Harbor Reward: {preview.get('reward')}")
            print("=======================================================")
            break

        game_over, res = play_one_step()
        steps_played += 1

        if game_over:
            print("\n=======================================================")
            print("MATCH COMPLETE!")
            status = http_get("/status")
            preview = status.get("harbor_score_preview", {})
            print(f"Final Score: You {preview.get('your_vp')} VP vs Automa {preview.get('automa_vp')} VP (Margin: +{preview.get('vp_margin')} VP)")
            print(f"Won: {preview.get('won')}")
            print(f"Harbor Reward: {preview.get('reward')}")
            print("=======================================================")
            break

        if args.step > 0 and steps_played >= args.step:
            print(f"\nPaused after {steps_played} step(s).")
            break

        time.sleep(0.05)

    elapsed = time.time() - start_time
    print(f"Completed in {elapsed:.1f}s ({steps_played} moves played).")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

