    url = f"{DAEMON_URL}{path}"
    body = json.dumps(data).encode("utf-8")
    headers = {"Content-Type": "application/json"}
    req = urllib.request.Request(url, data=body, headers=headers, method="POST")
    for attempt in range(3):
        try:
            with urllib.request.urlopen(req, timeout=timeout) as resp:
                return json.loads(resp.read().decode("utf-8"))
        except Exception as e:
            if attempt == 2:
                raise
            time.sleep(0.5)
    return {}


def is_connected_to_merchant(city: str, links: Dict[str, Any]) -> bool:
    if not city or city in MERCHANT_PORTS:
        return True
    if not links:
        return False
    visited: Set[str] = {city}
    queue: List[str] = [city]
    adj: Dict[str, Set[str]] = {}
    for lid in links.keys():
        parts = lid.split("-")
        for i in range(len(parts)):
            for j in range(i + 1, len(parts)):
                adj.setdefault(parts[i], set()).add(parts[j])
                adj.setdefault(parts[j], set()).add(parts[i])
    while queue:
        curr = queue.pop(0)
        if curr in MERCHANT_PORTS:
            return True
        for nxt in adj.get(curr, []):
            if nxt not in visited:
                visited.add(nxt)
                queue.append(nxt)
    return False


def get_current_level(ind_name: str, mat: Dict[str, List[int]]) -> int:
    counts = mat.get(ind_name, [])
    for lvl_idx, count in enumerate(counts):
        if count > 0:
            return lvl_idx + 1
    return 1


def parse_action_notes(formatted_text: str) -> Dict[int, Dict[str, Any]]:
    notes_by_id: Dict[int, Dict[str, Any]] = {}
    for line in formatted_text.splitlines():
        m = re.match(r"\s*\[\s*(\d+)\]\s*(.*)", line)
        if not m:
            continue
        aid = int(m.group(1))
        rest = m.group(2)
        notes = re.findall(r"\[([^\]]+)\]", rest)
        parsed: Dict[str, Any] = {
            "raw_notes": notes,
            "tile_vp": 0,
            "tile_inc": 0,
            "link_dots": 0,
            "link_vp": 0,
            "unlinked": False,
            "connects_merchant": False,
            "dev_tiles": 0,
            "loan_warn": False,
            "auto_flips": False,
        }
        for note in notes:
            mvp = re.search(r"(?:tile=|\+)?(\d+)VP", note)
            if mvp:
                parsed["tile_vp"] = int(mvp.group(1))
            minc = re.search(r"\+(\d+)inc", note)
            if minc:
                parsed["tile_inc"] = int(minc.group(1))
            mdot = re.search(r"(\d+)•", note)
            if mdot:
                parsed["link_dots"] = int(mdot.group(1))
            lvp = re.search(r"currently \+(\d+) link VP", note)
            if lvp:
                parsed["link_vp"] = int(lvp.group(1))
            if "not yet linked to matching merchant" in note:
                parsed["unlinked"] = True
            if "connects merchant port" in note:
                parsed["connects_merchant"] = True
            mdev = re.search(r"unlocks higher tech \((\d+) tiles\)", note)
            if mdev:
                parsed["dev_tiles"] = int(mdev.group(1))
            if "WARN" in note:
                parsed["loan_warn"] = True
            if "AUTO-FLIP" in note.upper():
                parsed["auto_flips"] = True
        notes_by_id[aid] = parsed
    return notes_by_id


def score_action(
    action: Dict[str, Any],
    state: Dict[str, Any],
    summary: Dict[str, Any],
    notes_dict: Dict[int, Dict[str, Any]],
) -> float:
    aid = action["action_id"]
    atype = action.get("action_type") or action.get("type", "")
    cost = action.get("cost", 0)
    note = notes_dict.get(aid, {})
    era = state.get("era", "canal")
    turn = state.get("turn", 1)
    money = state.get("money", 0)
    income_space = state.get("income_space", 10)
    links = state.get("links", {})
    mat = state.get("mat", {})

    is_late_era = (era == "canal" and turn >= 8) or (era == "rail" and (turn >= 8 or turn >= 18))
    is_very_late_era = (era == "canal" and turn >= 9) or (era == "rail" and (turn >= 9 or turn >= 19))
    is_early_era = turn <= 4

    score = 0.0
    score -= cost * 0.02

    if atype == "sell":
        score += 170.0
        sales = action.get("sales", [])
        if sales and isinstance(sales, list):
            score += len(sales) * 35.0
            for s in sales:
                if isinstance(s, dict):
                    score += s.get("vp", 0) * 8.0
                    score += s.get("income", 0) * 4.0
        else:
            score += note.get("tile_vp", 0) * 8.0
            score += note.get("tile_inc", 0) * 4.0
            score += note.get("link_dots", 0) * 6.0
        if is_late_era:
            score += 130.0

    elif atype == "network":
        is_double = action.get("is_double_rail", False)
        link_vp = note.get("link_vp", 0)
        connects_merch = note.get("connects_merchant", False)
        link_id = action.get("link_id", "")

        if era == "rail":
            if is_double:
                score += 150.0 + (link_vp * 8.0)
                if connects_merch:
                    score += 20.0
            else:
                score += 75.0 + (link_vp * 8.0)
                if connects_merch:
                    score += 15.0
        else:  # Canal era
            score += 50.0 + (link_vp * 7.0)
            if connects_merch:
                score += 35.0
            if turn == 1 and "birmingham-oxford" in link_id:
                score += 40.0
            if is_late_era and link_vp >= 3:
                score += 30.0

    elif atype == "build":
        ind = action.get("industry", "")
        level = action.get("level", 1)
        city = action.get("city", "")
        unlinked = note.get("unlinked", False)
        tile_vp = note.get("tile_vp", 0)
        tile_inc = note.get("tile_inc", 0)
        auto_flips = note.get("auto_flips", False)

        if city in CENTRAL_CITIES:
            score += 3.0

        if auto_flips:
            score += 65.0  # Instant flip, cash refund, and VP lock-in!

        if ind == "brewery":
            beer_count = summary.get("player_beer_barrels", 0)
            if era == "canal":
                if beer_count == 0:
                    score += 115.0 + tile_vp * 4.0
                else:
                    score += 65.0 + tile_vp * 3.0
                if level >= 2:
                    score += 40.0
            else:
                score += (150.0 if beer_count == 0 else 85.0) + tile_vp * 4.0

        elif ind == "coal":
            mine_cubes = summary.get("player_remaining_mine_cubes", 0)
            conn_merch = is_connected_to_merchant(city, links)
            coal_cubes = state.get("coal_cubes", 14)
            if conn_merch and coal_cubes < 14 and not auto_flips:
                score += 30.0
            if mine_cubes >= 2 and not auto_flips:
                score -= 60.0
            score += 60.0 + tile_vp * 5.0 + tile_inc * 4.0
            if era == "canal" and level >= 2:
                score += 35.0

        elif ind == "iron":
            iron_cubes = state.get("iron_cubes", 8)
            if iron_cubes < 14 and not auto_flips:
                score += 35.0
            score += 75.0 + tile_vp * 5.0 + tile_inc * 4.0
            if era == "canal" and level >= 2:
                score += 40.0

        elif ind in ("cotton", "goods", "pottery"):
            if unlinked:
                if is_late_era:
                    score -= 120.0
                elif turn <= 2:
                    score += 35.0
                else:
                    score += 25.0
            else:
                if level >= 2:
                    score += 110.0 + tile_vp * 6.0 + tile_inc * 3.0
                elif ind == "goods":
                    score += 40.0 + tile_vp * 4.0
                elif ind == "pottery":
                    score += 105.0 + tile_vp * 6.0 + tile_inc * 3.0
                else:
                    score += 80.0 + tile_vp * 5.0 + tile_inc * 3.0

        if era == "canal":
            if level >= 2 and ind not in ("coal", "iron", "brewery"):
                score += 40.0
            elif is_late_era:
                score -= 70.0

    elif atype == "develop":
        inds = action.get("industries", [])
        if era == "canal":
            if turn <= 5:
                score += 75.0
                for ind_name in inds:
                    cur_lvl = get_current_level(ind_name, mat)
                    if cur_lvl == 1:
                        if ind_name == "iron":
                            score += 18.0
                        elif ind_name in ("cotton", "brewery"):
                            score += 10.0
                    else:
                        score -= 25.0
            elif turn <= 7:
                score += 35.0
            else:
                score -= 60.0
        else:
            score += 20.0 if turn <= 14 else -80.0

    elif atype == "loan":
        if note.get("loan_warn", False) or is_very_late_era:
            score -= 250.0
        elif money >= 18:
            score -= 100.0
        elif money <= 7:
            if (era == "canal" and turn <= 6) or (era == "rail" and (turn <= 6 or turn <= 16)):
                score += 95.0
            else:
                score += 40.0
        elif money <= 13:
            score += 45.0
        else:
            score -= 20.0

        if income_space < 10:
            score -= 100.0

    elif atype == "scout":
        score -= 60.0

    elif atype == "pass":
        score -= 1000.0

    rem_money = money - cost
    if rem_money < 2 and income_space <= 10 and turn > 1 and atype not in ("sell", "loan") and not note.get("auto_flips", False):
        score -= 15.0

    return score


def play_one_step() -> Tuple[bool, Dict[str, Any]]:
    status = http_get("/status")
    if not status.get("ok"):
        print(f"Status error: {status.get('error')}", file=sys.stderr)
        return False, status

    state = status.get("state", {})
    if state.get("game_over"):
        print("Game is already over!")
        return True, status

    legal = http_get("/legal")
    if not legal.get("ok"):
        print(f"Legal error: {legal.get('error')}", file=sys.stderr)
        return False, legal

    actions = legal.get("actions", [])
    if not actions:
        print("No legal actions available!")
        return True, status

    notes = parse_action_notes(legal.get("formatted", ""))
    summary = status.get("board_summary", {})

    scored: List[Tuple[float, Dict[str, Any]]] = []
    for a in actions:
        s = score_action(a, state, summary, notes)
        scored.append((s, a))

    scored.sort(key=lambda x: x[0], reverse=True)
    best_score, best_action = scored[0]
    aid = best_action["action_id"]

    print(f"\n--- SELECTING ACTION ---")
    print(f"State: Era={state.get('era')} | Turn={state.get('turn')} | ActionsLeft={state.get('actions_left')} | Cash=£{state.get('money')} | Inc={summary.get('income_pounds')} | VP={state.get('your_vp')} vs Automa={state.get('automa_vp')}")
    print(f"Chosen: [{aid:2d}] {best_action.get('description')} (Heuristic Score: {best_score:.1f})")
    if len(scored) > 1:
        s2, a2 = scored[1]
        print(f"Runner-up: [{a2['action_id']:2d}] {a2.get('description')} (Score: {s2:.1f})")

    result = http_post("/play", {"action_id": aid})
    if not result.get("ok"):
        print(f"Play ERROR: {result.get('error')}", file=sys.stderr)
        return False, result

    print(f">>> EXECUTED STEP #{result.get('executed_step')}: [{result.get('executed_action_id')}] {result.get('executed_description')}")

    game_over = result.get("game_over", False)
    return game_over, result


def main() -> int:
    parser = argparse.ArgumentParser(description="Brass Birmingham Autonomous Controller")
    parser.add_argument("--step", type=int, default=0, help="Play N steps (0 for run to completion)")
    args = parser.parse_args()

    steps_played = 0
    start_time = time.time()

    while True:
        status = http_get("/status")
        if status.get("state", {}).get("game_over"):
            print("\n=======================================================")
            print("MATCH COMPLETE!")
            preview = status.get("harbor_score_preview", {})
            print(f"Final Score: You {preview.get('your_vp')} VP vs Automa {preview.get('automa_vp')} VP (Margin: +{preview.get('vp_margin')} VP)")
            print(f"Won: {preview.get('won')}")
            print(f"Harbor Reward: {preview.get('reward')}")
            print("=======================================================")
            break

        game_over, res = play_one_step()
        steps_played += 1

        if game_over:
            print("\n=======================================================")
            print("MATCH COMPLETE!")
            status = http_get("/status")
            preview = status.get("harbor_score_preview", {})
            print(f"Final Score: You {preview.get('your_vp')} VP vs Automa {preview.get('automa_vp')} VP (Margin: +{preview.get('vp_margin')} VP)")
            print(f"Won: {preview.get('won')}")
            print(f"Harbor Reward: {preview.get('reward')}")
            print("=======================================================")
            break

        if args.step > 0 and steps_played >= args.step:
            print(f"\nPaused after {steps_played} step(s).")
            break

        time.sleep(0.05)

    elapsed = time.time() - start_time
    print(f"Completed in {elapsed:.1f}s ({steps_played} moves played).")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

